/* Two local workshop collections. Original photographs and documented processes;
 * shared navigation/zoom, without changing the six main projects. */
(()=>{
 const folder='experiments-r12/';
 const collections=[
  {id:'impressio-3d',title:'Impressió 3D',display:'Impressió 3D',heading:'Impressió<br>3D',experiment:true,className:'print3d',cover:'workshop-r15/marieta-foto.webp',alt:'Penjador Marieta vermell amb braços de fusta i una jaqueta penjada, sobre fons blau',lead:'Exploracions de forma, encaixos i muntatge mitjançant la impressió 3D.',pieces:[
   {id:'rellotge',title:'Rellotge de paret',description:'Rellotge de paret octogonal imprès en PLA blanc. El disseny es divideix en tres peces unides amb encaixos i cargols, amb un espai interior per allotjar el mecanisme.',learningTitle:'Ajust dels encaixos.',learning:'El projecte m’ha ajudat a plantejar la divisió d’un objecte segons la mida de la impressora i les necessitats de muntatge. Algunes unions van requerir un repàs amb llima: una prova prèvia dels encaixos hauria permès ajustar millor els marges entre peces.',photo:'rellotge-resultat',alt:'Rellotge físic de PLA blanc amb esfera octogonal i agulles, recolzat sobre un fons vermell',caption:'Resultat de la impressió · PLA blanc',detail:'rellotge-muntatge',detailAlt:'Peces blanques del rellotge separades, abans de muntar l’esfera i el mecanisme',detailCaption:'Les peces, abans del muntatge'},
   {id:'contrapposto',title:'Contrapposto',description:'Maqueta impresa en 3D de l’ampolla d’oli Contrapposto, utilitzada per comprovar les proporcions i valorar la relació entre el cos, la base i el coll.',learningTitle:'Comprovació del volum.',learning:'La impressió m’ha permès contrastar el modelatge de superfícies amb Rhinoceros amb una referència física. Observar la maqueta des de diferents angles facilita la valoració del perfil i de les proporcions.',photo:'contrapposto-front',alt:'Vista frontal de la maqueta física de Contrapposto impresa en color clar',caption:'Maqueta impresa · Vista de davant',detail:'contrapposto-perfil',detailAlt:'Vista lateral de la maqueta impresa de Contrapposto, amb l’aresta i el perfil asimètric visibles',detailCaption:'Vista de costat',related:{href:'#/project/ampolla-oli',label:'Veure el projecte Contrapposto'}},
   {id:'penjador',title:'Marieta',description:'Penjador de paret en forma de marieta, amb un cos vermell imprès en 3D i dos braços de fusta. El disseny incorpora els encaixos dels braços i les ranures de fixació al revers.',learningTitle:'Del model a l’objecte.',learning:'El desenvolupament m’ha permès treballar la relació entre el model 3D, la impressió i el muntatge final. Els punts principals han estat l’encaix entre plàstic i fusta i la fixació del conjunt a la paret.',photo:'workshop-r15/marieta-foto',alt:'Penjador Marieta fabricat en vermell, amb dos braços de fusta sostenint una jaqueta sobre fons blau',caption:'El penjador en ús · Impressió 3D i fusta',detail:'workshop-r15/marieta-front',detailAlt:'Render frontal del cos vermell de Marieta, amb els orificis per als braços de fusta',detailCaption:'Cos imprès · Vista frontal',extra:'workshop-r15/marieta-darrere',extraAlt:'Render posterior del cos de Marieta amb les ranures de fixació a la paret',extraCaption:'Fixació a la paret · Vista posterior',credit:'Treball en equip amb Paula Cifuentes i Blanca Gordillo.'}
  ]},
  {id:'maquetes-i-prototips',title:'Maquetes i prototips',display:'Maquetes i prototips',heading:'Maquetes<br>i prototips',experiment:true,className:'models',cover:folder+'tamboret-tres-quarts.webp',alt:'Maqueta física del tamboret amb el seient vermell i l’estructura grisa, vista de tres quarts',lead:'Maquetes de taller per estudiar proporcions, materials, muntatge i ús.',pieces:[
   {id:'lip-kit',title:'Lip Kit',description:'Envàs de cartró per a un pintallavis i un perfilador. La tapa amb tall diagonal es recol·loca sota el cos com a base, de manera que l’envàs obert funciona també com a suport per als productes.',learningTitle:'Del desplegable al volum.',learning:'He treballat el desplegable, els plecs i les zones d’enganxat, així com la continuïtat de la gràfica entre les cares. La maqueta ha servit per comprovar l’obertura i l’estabilitat de l’envàs.',photo:'workshop-r16/lip-kit-tancat',alt:'Prototip físic tancat de Lip Kit, amb la gràfica rosa i vermella i una obertura superior',caption:'Prototip de cartró · Envàs tancat',detail:'workshop-r16/lip-kit-obert',detailAlt:'Maqueta de Lip Kit oberta amb els dos cosmètics visibles i la tapa separada',detailCaption:'Obertura i accés als productes',credit:'Exercici de disseny d’envasos a partir de Lip Kit de Kylie Cosmetics.'},
   {id:'tamboret',title:'Maqueta d’un tamboret',description:'Reproducció d’un tamboret a partir de plànols i fotografies. El seient està treballat en escuma de poliuretà i l’estructura es construeix amb varetes de PVC, amb acabats en vermell i gris.',learningTitle:'Treballar el volum a mà.',learning:'El treball m’ha ajudat a controlar la talla i el polit de l’escuma. La dificultat principal ha estat reproduir els detalls del seient sense perdre volum i preparar una superfície uniforme abans de pintar.',photo:'tamboret-tres-quarts',alt:'Maqueta física del tamboret vista de tres quarts, amb seient vermell i estructura grisa',caption:'Maqueta · Vista de tres quarts',detail:'tamboret-frontal',detailAlt:'Vista frontal de la maqueta del tamboret, amb els volums i els detalls del seient vermell',detailCaption:'Proporcions i detalls del seient',credit:'Maqueta de Marc Moncunill · Exercici de reproducció.'},
   {id:'kyoto',title:'Kyoto',description:'Maqueta d’un comandament domèstic construïda per capes desmuntables. Permet estudiar el muntatge, l’encaix entre les peces i l’espai reservat al mecanisme.',learningTitle:'Pensar el muntatge per capes.',learning:'El prototip m’ha permès comprovar els encaixos i la distribució interior. El muntatge desmuntable facilita la revisió de cada capa i l’explicació del conjunt.',photo:'kyoto-frontal',alt:'Maqueta de Kyoto en posició vertical, amb els marcs negres concèntrics sobre la base blanca',caption:'Maqueta física · Conjunt tancat',detail:'kyoto-muntatge',detailAlt:'Prototip Kyoto desmuntat amb el marc retirat i el mecanisme interior a la vista',detailCaption:'Capes i espai per al mecanisme'}
  ]}
 ];
 const full=name=>(name.includes('/')?'':folder)+name+'.webp';
 function photo(name,alt,caption,primary=false,eager=false){const file=full(name),sizes=name.includes('lip-kit')?(primary?'(max-width:700px) 516px, (max-width:1000px) 498px, (max-width:1375px) 57vw, 783px':'(max-width:700px) 392px, (max-width:1000px) 392px, (max-width:1417px) 43vw, 605px'):name.endsWith('marieta-foto')?'(max-width:700px) 80vw, (max-width:1000px) 52vw, 66vw':primary?'(max-width:700px) 54vw, (max-width:1000px) 43vw, 29vw':'(max-width:700px) 36vw, (max-width:1000px) 34vw, 23vw';return `<figure class="${primary?'workshop-primary':'workshop-detail'}"><button class="image-button" data-image="${file}" data-caption="${caption}" aria-label="Amplia: ${alt}">${mediaImage(file,alt,eager,sizes)}</button><figcaption>${caption}</figcaption></figure>`;}
 function piece(p,index){return `<section class="workshop-row${index%2?' is-reversed':''}" id="taller-${p.id}" data-piece="${p.id}" aria-labelledby="taller-${p.id}-title"><div class="workshop-visuals">${photo(p.photo,p.alt,p.caption,true,index===0)}${photo(p.detail,p.detailAlt,p.detailCaption)}${p.extra?photo(p.extra,p.extraAlt,p.extraCaption):''}</div><div class="workshop-copy"><h2 id="taller-${p.id}-title">${p.title}</h2><p>${p.description}</p><div class="workshop-learning"><h3>${p.learningTitle}</h3><p>${p.learning}</p></div>${p.credit?`<p class="workshop-credit">${p.credit}</p>`:''}${p.related?`<a class="workshop-related" href="${p.related.href}">${p.related.label} <span aria-hidden="true">↗</span></a>`:''}</div></section>`;}
 function render(p){
  const next=collections.find(item=>item.id!==p.id);
  return `<article class="project workshop-case workshop-${p.className}"><section class="workshop-heading" aria-label="Presentació de ${p.title}"><div><a class="workshop-back" href="#/#experimentacio">← Experimentació</a><h1>${p.heading}</h1></div><div class="workshop-lead"><p>${p.lead}</p><nav class="workshop-links" aria-label="Treballs de ${p.title}">${p.pieces.map(item=>`<a href="#/experimentacio/${p.id}/${item.id}">${item.title}</a>`).join('')}</nav></div></section><div class="workshop-pieces">${p.pieces.map(piece).join('')}</div><a class="workshop-next" href="#/experimentacio/${next.id}"><span><span class="workshop-next-label">Més experimentació</span><strong>${next.title}</strong><span aria-hidden="true">↗</span></span>${mediaImage(next.cover,next.alt,false,'(max-width:700px) 42vw, 22vw')}</a></article>`;
 }
 function index(){return `<div class="experiment-grid workshop-index-row" style="--workshop-columns:${collections.map(p=>{const d=imageMetadata[p.cover];return (d.width/d.height).toFixed(6)+'fr';}).join(' ')}">${collections.map(card).join('')}</div>`;}
 function destination(hash){const match=hash.match(/^#\/experimentacio\/(impressio-3d|maquetes-i-prototips)\/([a-z0-9-]+)$/);return match&&collections.find(p=>p.id===match[1])?.pieces.some(p=>p.id===match[2])?document.getElementById('taller-'+match[2]):null;}
 window.portfolioWorkshops={items:collections,render,index,destination,has:id=>collections.some(p=>p.id===id)};
})();
